fn solve(input: Vec<char>) -> Vec<char> {
    if check_all_lowercase(&input) {
        vec!['a']
    } else {
        vec!['A']
    }
}

fn check_all_lowercase(v: &Vec<char>) -> bool {
    // Check if the vector is not empty and all characters are lowercase letters
    !v.is_empty() && v.iter().all(|&c| c.is_ascii_lowercase())
}

fn main() {
    // Example usage
    let input1 = vec!['a', 'b', 'c'];
    let input2 = vec!['A', 'b', 'c'];
    let input3 = vec![];

    println!("{:?}", solve(input1)); // Output: ['a']
    println!("{:?}", solve(input2)); // Output: ['A']
    println!("{:?}", solve(input3)); // Output: ['A']
}